async function e6() {
  const closed = await freePort(); // nothing listens here
  const px = await startProxy({ UPSTREAM: `http://127.0.0.1:${closed}`, RETRIES: "0" });
  try {
    const res = await fetch(`${px.url}/`);
    await res.text();
    await sleep(100);
    const q = px.requests()[0];
    return { title: "E6 - which error does a closed port give?", note: "...", columns: ["platform", "status", "error"], rows: [[process.platform, res.status, q.error]], raw: [q] };
  } finally { await px.stop(); }
}
